function solution() {
  const requests = new Map();
  const LIMIT = 100;
  const WINDOW = 60000;

  return function isAllowed(ip) {
    const now = Date.now();
    const timestamps = requests.get(ip) || [];
    const valid = timestamps.filter(t => now - t < WINDOW);

    if (valid.length >= LIMIT) {
      requests.set(ip, valid);
      return false;
    }

    valid.push(now);
    requests.set(ip, valid);
    return true;
  };
}

